const out = (($input.first().json.stdout) || '') + '';
const sec = (name) => { const parts = out.split('===' + name + '==='); if (parts.length < 2) return ''; return parts[1].split('===')[0]; };
const containers = sec('CONTAINERS').trim().split('\n').filter(Boolean).map(function(l){ const p = l.split('|'); return { name:p[0], state:p[1]||'', status:p[2]||'', oom:(p[3]==='true'), restarts:parseInt(p[4]||'0',10)||0, exit:parseInt(p[5]||'0',10)||0 }; });
const disk = sec('DISK').trim().split('\n').filter(Boolean).map(function(l){ const p = l.split('|'); return { type:p[0], size:p[1], reclaimable:p[2] }; });
const logs = sec('LOGS').trim();
const problems = [];
for (const c of containers) {
  if (c.state === 'exited' && c.exit !== 0) problems.push({ cible:c.name, type:'infra', gravite:'haute', signal:'conteneur arrete (exit ' + c.exit + ')', action:'restart' });
  else if (c.oom) problems.push({ cible:c.name, type:'infra', gravite:'haute', signal:'tue par OOM (memoire insuffisante)', action:'restart' });
  else if (/unhealthy/.test(c.status)) problems.push({ cible:c.name, type:'infra', gravite:'moyenne', signal:'healthcheck KO (unhealthy)', action:'restart' });
  else if (c.state !== 'running' && c.state !== 'created') problems.push({ cible:c.name, type:'infra', gravite:'moyenne', signal:'etat ' + c.state, action:'restart' });
  if (c.restarts >= 5) problems.push({ cible:c.name, type:'infra', gravite:'moyenne', signal:'boucle de redemarrage (' + c.restarts + ' restarts)', action:'inspecter' });
}
const gb = function(s){ const m = /([0-9.]+)\s*GB/.exec(s || ''); return m ? parseFloat(m[1]) : 0; };
for (const d of disk) { if ((d.type === 'Build Cache' || d.type === 'Images') && gb(d.reclaimable) >= 2) problems.push({ cible:'docker/' + d.type, type:'infra', gravite:'basse', signal:d.type + ' recuperable ' + d.reclaimable, action:'prune' }); }
const errLines = logs.split('\n').filter(function(l){ return /error|exception|unhandled|econnrefused|fatal|panic|traceback|\b5\d\d\b/i.test(l); }).slice(0, 40);
if (errLines.length) problems.push({ cible:'logs applicatifs', type:'applicatif', gravite:'a trier', signal:errLines.length + ' ligne(s) d erreur dans les logs', action:'triage' });
return [{ json: { hasProblems: problems.length > 0, nbProblemes: problems.length, problems, containers, disk, logSample: errLines.join('\n').slice(0, 4000), generatedAt: new Date().toISOString() } }];

const det = $('Detecter').first().json;
let ai = null;
try { const r = $('Triage IA (Claude)').first().json; if (r && Array.isArray(r.content)) { const txt = (r.content.find(function(b){ return b.type === 'text'; }) || {}).text || ''; const s = txt.indexOf('{'); const e = txt.lastIndexOf('}'); if (s >= 0 && e > s) ai = JSON.parse(txt.slice(s, e + 1)); } } catch (err) { ai = null; }
// Rapport lisible
const lines = [];
lines.push('*ERP Seem Semrac — ' + det.nbProblemes + ' incident(s) detecte(s)* (' + det.generatedAt + ')');
if (ai && ai.synthese) lines.push('_Synthese IA :_ ' + ai.synthese);
for (const p of det.problems) {
  let extra = '';
  if (ai && Array.isArray(ai.incidents)) { const m = ai.incidents.find(function(x){ return (x.cible || '').indexOf(p.cible) >= 0 || p.cible.indexOf(x.cible || '') >= 0; }); if (m) { extra = ' — [' + (m.classe || '?') + '] ' + (m.diagnostic || ''); if (m.correctif_propose) extra += ' | Correctif propose : ' + m.correctif_propose; } }
  lines.push('• [' + p.type + '/' + p.gravite + '] ' + p.cible + ' : ' + p.signal + extra);
}
const report = lines.join('\n');
// Reparation infra BORNEE : liste blanche + plafond, jamais de volumes, jamais de patch de code
const ALLOW = ['erp-app','erp-kong','erp-rest','erp-storage','erp-meta','erp-studio','erp-imgproxy','erp-db'];
const restarts = [];
for (const p of det.problems) { if (p.type === 'infra' && p.action === 'restart' && ALLOW.indexOf(p.cible) >= 0) restarts.push(p.cible); }
const uniqRestarts = restarts.filter(function(v, i){ return restarts.indexOf(v) === i; }).slice(0, 3);
const needPrune = det.problems.some(function(p){ return p.action === 'prune'; });
const cmds = [];
for (const n of uniqRestarts) cmds.push('docker restart ' + n);
if (needPrune) { cmds.push('docker image prune -f'); cmds.push('docker builder prune -f'); }
const repairCmd = cmds.length ? cmds.join(' ; ') : 'echo \"aucune action infra sure\"';
const autoheal = (($env.AUTOHEAL_ENABLED || 'false') + '').toLowerCase() === 'true';
return [{ json: { report, repairCmd, autoheal, canRepair: (autoheal && cmds.length > 0), actions: cmds } }];
